using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using UnityEngine;using UnityEngine.UI;using UnityEngine.Scripting;
namespace RailDrivingSimulator {
 public partial class Game {
  public static bool Mobile {get{return Application.platform==RuntimePlatform.IPhonePlayer||Application.isMobilePlatform;}}
  bool waitingVigilance;MapImportJob activeImport;string pickedTemp;Slider notchSlider;Text notchText;RectTransform mobileRoot;Rect safeLast;int widthLast,heightLast;
#if UNITY_IOS && !UNITY_EDITOR
  [DllImport("__Internal")]static extern void RailPickDocument(string receiver);
  [DllImport("__Internal")]static extern long RailAvailableBytes();
#endif
  void PickIOS(){
#if UNITY_IOS && !UNITY_EDITOR
   Clear("选择地图文件");Label("请在系统“文件”窗口选择 iOS .railmap。云端文件需要先下载。",28);RailPickDocument(gameObject.name);
#else
   ImportMenu();
#endif
  }
  [Preserve]public void OnIOSMapPicked(string path){if(string.IsNullOrEmpty(path)){ImportMenu();return;}if(path.StartsWith("ERROR:")){Error(path.Substring(6));return;}pickedTemp=path;StartCoroutine(ImportMap(path));}
  void IOSImportMenu(){Clear("导入iOS地图");Label("应用不内置地图。请选择单独提供的 _iOS.railmap；支持本地文件和 iCloud Drive。",28);Button("浏览文件并导入",PickIOS);Button("管理已导入地图",MobileMaps);Button("返回",Menu);}
  void MobileSettings(Action back){Clear("移动版设置");Button("画质："+new[]{"标准","高","极端","极端（高）"}[cfg.quality],()=>{cfg.quality=(cfg.quality+1)%4;ApplyQuality();cfg.Save();MobileSettings(back);});Label("极端目标30FPS；极端（高）画面优先，可能低于30FPS。",28);Button("音量："+Mathf.RoundToInt(cfg.volume*100)+"%",()=>{cfg.volume=(cfg.volume+.1f)%1.1f;cfg.Save();MobileSettings(back);});Button("视角灵敏度："+cfg.sensitivity.ToString("F1"),()=>{cfg.sensitivity=cfg.sensitivity>=3?.5f:cfg.sensitivity+.5f;cfg.Save();MobileSettings(back);});Button("返回",back);}
  void MobileMaps(){Clear("地图管理");maps=MapCatalog.Discover();foreach(var m in maps){var map=m;long size=Directory.GetFiles(map.folder,"*",SearchOption.AllDirectories).Sum(f=>new FileInfo(f).Length);Label(map.Name+"  "+(size/1048576)+" MB",28);Button("删除："+map.Name,()=>{Clear("确认删除地图？");Label(map.Name);Button("确认删除",()=>{Directory.Delete(map.folder,true);MobileMaps();});Button("取消",MobileMaps);});}if(maps.Count==0)Label("还没有导入地图。");Button("返回",IOSImportMenu);}
  System.Collections.IEnumerator CleanupImportTask(System.Threading.Tasks.Task task,string file){while(!task.IsCompleted)yield return null;if(!string.IsNullOrEmpty(file))try{File.Delete(file);}catch{}}
  void CleanPickedFile(){if(!string.IsNullOrEmpty(pickedTemp)){try{File.Delete(pickedTemp);}catch{}pickedTemp=null;}}
  RectTransform MobileArea(string name,Vector2 lo,Vector2 hi,Color color){var o=new GameObject(name,typeof(RectTransform),typeof(Image));var r=o.GetComponent<RectTransform>();r.SetParent(mobileRoot?mobileRoot:(RectTransform)canvas.transform,false);r.anchorMin=lo;r.anchorMax=hi;r.offsetMin=r.offsetMax=Vector2.zero;o.GetComponent<Image>().color=color;return r;}
  Button MobileButton(string text,Vector2 lo,Vector2 hi,Action click){var r=MobileArea(text,lo,hi,new Color(.055f,.11f,.15f,.86f));var b=r.gameObject.AddComponent<Button>();var t=Label(text,28,r);t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=t.rectTransform.offsetMax=Vector2.zero;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;b.onClick.AddListener(()=>{try{click();}catch(Exception e){Error(e.Message);}});return b;}
  void HoldButton(string label,string action,Vector2 lo,Vector2 hi){var b=MobileButton(label,lo,hi,()=>{});var hold=b.gameObject.AddComponent<MobileHold>();hold.action=action;}
  void TouchDrivingUI(){MobileInput.Clear();mobileRoot=new GameObject("SafeArea",typeof(RectTransform)).GetComponent<RectTransform>();mobileRoot.SetParent(canvas.transform,false);widthLast=heightLast=-1;RefreshSafeArea();var region=MobileArea("拖动转视角",new Vector2(.21f,.19f),new Vector2(.83f,.81f),Color.clear);var look=region.gameObject.AddComponent<MobileLook>();look.turn=delta=>{yaw+=delta.x/Screen.width*160*cfg.sensitivity;pitch=Mathf.Clamp(pitch-delta.y/Screen.height*100*cfg.sensitivity,-75,75);};
   MobileButton("开门",new Vector2(.015f,.57f),new Vector2(.19f,.69f),()=>MobileInput.Press("开门"));MobileButton("关门",new Vector2(.015f,.43f),new Vector2(.19f,.55f),()=>MobileInput.Press("关门"));HoldButton("鸣笛","喇叭",new Vector2(.015f,.29f),new Vector2(.19f,.41f));if(sim.state.plan.difficulty!=Difficulty.Normal)HoldButton("按住警惕","防失能",new Vector2(.015f,.09f),new Vector2(.19f,.27f));
   MobileButton("EB",new Vector2(.84f,.02f),new Vector2(.985f,.14f),()=>MobileInput.Press("紧急制动"));MobileButton("+",new Vector2(.84f,.70f),new Vector2(.985f,.81f),()=>MobileInput.Press("牵引增档"));MobileButton("−",new Vector2(.84f,.17f),new Vector2(.985f,.28f),()=>MobileInput.Press("制动增档"));
   var sr=MobileArea("有级手柄",new Vector2(.86f,.30f),new Vector2(.97f,.67f),new Color(.06f,.09f,.12f,.9f));notchSlider=sr.gameObject.AddComponent<Slider>();notchSlider.direction=Slider.Direction.BottomToTop;notchSlider.minValue=1-sim.state.plan.train.brake.Length;notchSlider.maxValue=sim.state.plan.train.power.Length-1;notchSlider.wholeNumbers=true;var handle=new GameObject("Handle",typeof(RectTransform),typeof(Image)).GetComponent<RectTransform>();handle.SetParent(sr,false);handle.sizeDelta=new Vector2(0,70);handle.GetComponent<Image>().color=new Color(.5f,.9f,.65f);notchSlider.handleRect=handle;notchSlider.targetGraphic=handle.GetComponent<Image>();notchSlider.SetValueWithoutNotify(sim.state.notch);notchSlider.onValueChanged.AddListener(v=>{if(!paused){sim.state.notch=Mathf.RoundToInt(v);MobileHaptics.Tick();}});notchText=Label("N",28,handle);notchText.rectTransform.anchorMin=Vector2.zero;notchText.rectTransform.anchorMax=Vector2.one;notchText.rectTransform.offsetMin=notchText.rectTransform.offsetMax=Vector2.zero;notchText.alignment=TextAnchor.MiddleCenter;notchText.color=Color.black;notchText.raycastTarget=false;
   MobileButton("惰行 N",new Vector2(.23f,.02f),new Vector2(.36f,.14f),()=>MobileInput.Press("惰行"));MobileButton("视角",new Vector2(.38f,.02f),new Vector2(.51f,.14f),()=>MobileInput.Press("切换视角"));MobileButton("回正",new Vector2(.53f,.02f),new Vector2(.66f,.14f),()=>MobileInput.Press("视角归正"));MobileButton("更多",new Vector2(.68f,.02f),new Vector2(.81f,.14f),MobileMore);MobileButton("暂停",new Vector2(.84f,.84f),new Vector2(.985f,.97f),Pause);
   hud.fontSize=25;var bg=hud.transform.parent.GetComponent<RectTransform>();bg.SetParent(mobileRoot,false);bg.anchorMin=new Vector2(.015f,.82f);bg.anchorMax=new Vector2(.82f,.99f);bg.offsetMin=bg.offsetMax=Vector2.zero;bg.GetComponent<Image>().raycastTarget=false;hud.raycastTarget=false;
   waitingVigilance=sim.state.plan.difficulty!=Difficulty.Normal&&Math.Abs(sim.state.v)>.05;if(waitingVigilance){paused=true;sim.Message="恢复前先按住警惕按钮";}
  }
  void MobileMore(){paused=true;MobileInput.Clear();Clear("驾驶操作");foreach(var action in new[]{"紧急复位","启车确认","开门侧左","开门侧右","方向前进","方向中立","方向后退","雨刷","前照灯"}){string a=action;Button(a,()=>{MobileInput.Press(a);Commands();DrivingUI();});}Button("返回驾驶",DrivingUI);}
  void RefreshSafeArea(){if(!mobileRoot)return;var safe=Screen.safeArea;if(safe==safeLast&&Screen.width==widthLast&&Screen.height==heightLast)return;safeLast=safe;widthLast=Screen.width;heightLast=Screen.height;mobileRoot.anchorMin=new Vector2(safe.x/Screen.width,safe.y/Screen.height);mobileRoot.anchorMax=new Vector2(safe.xMax/Screen.width,safe.yMax/Screen.height);mobileRoot.offsetMin=mobileRoot.offsetMax=Vector2.zero;}
  void MobileFrame(){RefreshSafeArea();if(waitingVigilance&&MobileInput.Held("防失能")){waitingVigilance=false;paused=false;}if(notchSlider&&sim!=null){notchSlider.SetValueWithoutNotify(sim.state.notch);notchText.text=sim.state.emergency?"EB":sim.state.notch==0?"N":sim.state.notch>0?"P"+sim.state.notch:"B"+(-sim.state.notch);}}
  void OnApplicationPause(bool value){if(activeImport!=null)activeImport.Paused=value;if(value){MobileInput.Clear();if(sim!=null&&!loading)Pause();}}
  void MobileLowMemory(){if(world)world.radius=Mathf.Max(650,world.radius-200);if(sim!=null)sim.Message="内存预算调整：缩短地图预加载范围";}
  void MobileQuality(UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset pipe){Application.targetFrameRate=30;cam.farClipPlane=new[]{1600,2200,2800,3500}[cfg.quality];QualitySettings.shadowDistance=new[]{110,200,300,450}[cfg.quality];Shader.SetGlobalFloat("_RailMobile",1);if(pipe){pipe.mainLightShadowmapResolution=new[]{1024,2048,4096,4096}[cfg.quality];pipe.shadowDistance=QualitySettings.shadowDistance;pipe.shadowCascadeCount=cfg.quality<2?2:4;pipe.renderScale=new[]{.72f,.82f,.88f,1f}[cfg.quality];pipe.msaaSampleCount=2;}}
 }
}
